window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5902ee99c9e4eed4"]={"versions": [{"id": "FIG-5902ee99c9e4eed4", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Tabellarisches Konfigurations- und Zuordnungsmodell (Lookup-/Mapping-Tabelle für Zustandsübergänge).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Functional Cluster <strong>State Management (SM)</strong> (<code>AUTOSAR_SWS_StateManagement</code>, Kapitel 7 <em>Functional Specification</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition deterministischer, unbedingter Fehler-Wiederherstellungsübergänge (<em>unconditional recovery transitions</em>) innerhalb einer SM-Zustandsmaschine (<em>StateMachine</em>). Die Tabelle verknüpft platform- bzw. prozessseitig detektierte Laufzeitfehler (gemeldet durch <strong>Execution Management / EM</strong> oder <strong>Platform Health Management / PHM</strong>) direkt mit definierten Folgezuständen (z. B. Notlauf, Degradierung, Prozess-Restart, Safe State).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Datenstruktur:</strong></li>\n<li><strong><code>ErrorRecoveryTable</code>:</strong> Konfigurations-Artefakt im State-Management-Metamodell zur Abbildung von Fehlerereignissen auf Zielzustände.</li>\n<li><strong><code>Execution Error</code> (Spalte 1):</strong> Diskrete numerische Fehlerbezeichner (<code>uint32</code>/Integer-Werte), die spezifische Fehlerursachen oder Exit-Zustände von Prozessen bzw. Function Groups abbilden (im Schaubild: <code>11</code>, <code>12</code>, <code>111</code>, <code>23</code>, <code>24</code>, <code>244</code>). Im Metamodell korrespondieren diese mit Attributen des Typs <code>ProcessExecutionError.executionError</code>.</li>\n<li><strong><code>Next State</code> (Spalte 2):</strong> Zielzustands-Identifikatoren bzw. Indizes der Zustandsmaschine (<code>0</code>, <code>2</code>, <code>3</code>, <code>4</code>, <code>5</code>), die nach Auftreten des zugehörigen Fehlers eingenommen werden müssen.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>$N : 1$-Relation:</strong> Mehrere disjunkte Fehlerursachen können auf denselben Folgezustand abgebildet werden (z. B. führen sowohl Fehler <code>11</code> als auch <code>111</code> zu <code>Next State = 2</code>).</li>\n<li><strong>$1 : 1$-Eindeutigkeit:</strong> Jedem definierten <code>Execution Error</code> ist innerhalb der Tabelle genau ein deterministischer <code>Next State</code> zugewiesen (Injektivität vom Fehler auf den Folgezustand; keine Mehrdeutigkeit/Nicht-Determinismus).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Fehlerdetektion & Signalisierung (Trigger):</strong> Ein Prozess terminiert fehlerhaft, verletzt Watchdog-/Deadline-Vorgaben oder meldet einen Ausfall an PHM/EM. EM/PHM meldet das resultierende <code>ExecutionError</code>-Ereignis asynchron an den State Management Cluster.</li>\n<li><strong>Tabellen-Lookup:</strong> SM fängt das Ereignis ab und evaluiert die <code>ErrorRecoveryTable</code> der betroffenen Zustandsmaschine anhand des empfangenen numerischen Fehlercodes.</li>\n<li>*<em>Unbedingter Zustandsübergang (</em>Unconditional Transition<em>):</em>*</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wird ein passender Eintrag gefunden, feuert der Zustandsübergang priorisiert und unmittelbar – reguläre Transition-Guards oder Einträge aus der <code>TransitionRequestTable</code> werden umgangen.</li>\n<li>Das System wechselt in den konfigurierten <code>Next State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Folgeaktionen:</strong> SM leitet Aktionen zur Fehlerbehebung ein (z. B. Anforderung neuer Function-Group-Zustände via <code>ara::exec</code>, Herunterfahren kompromittierter Prozesse oder System-Fallback nach <code>State 0</code>).</li>\n<li><strong>Abbruch-/Fehlerfall:</strong> Trifft ein <code>Execution Error</code> ein, der in der <code>ErrorRecoveryTable</code> nicht hinterlegt ist, greift das plattformspezifische Default-Verhalten (z. B. Übergang in einen globalen Machine-Safe-State oder System-Reset).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration im Execution- & SM-Manifest (ARXML):</strong></li>\n<li>Systemintegratoren müssen alle relevanten Exit-Codes und Health-Fehler (<code>ProcessExecutionError</code>) lückenlos auf gültige <code>ModeDeclaration</code>-Zustände mappen.</li>\n<li>Lücken in der Tabelle führen bei nicht abgefangenen Fehlern zu undefiniertem Verhalten oder unkontrollierten Platform-Resets.</li>\n<li><strong>Prioritätsmodell gegenüber <code>TransitionRequestTable</code>:</strong></li>\n<li>Einträge der <code>ErrorRecoveryTable</code> besitzen strikten Vorrang vor regulären externen Zustandsanfragen (z. B. von der <code>SMControlApplication</code> oder via Network Management).</li>\n<li><strong>Vermeidung von Reset-/Restart-Schleifen (Safety-Design nach ISO 26262):</strong></li>\n<li>Applikations- und Stack-Entwickler müssen sicherstellen, dass wiederkehrende Fehler nicht in unendlichen Übergangszyklen enden (z. B. ständiges Wiederanlaufen über denselben Folgezustand). Zustandsmaschinen müssen Zähler- oder Eskalationsstrategien für persistente Fehler vorsehen.</li>\n<li><strong>API-Vertrag:</strong></li>\n<li>Adaptive Applications müssen ihre internen Fehlerbehandlungsroutinen und Prozess-Rückgabewerte auf die numerischen Definitionen der <code>Execution Error</code>-Tabelle der jeweiligen Machine- und Function-Group-Konfiguration abstimmen.</li>\n</ul>"}, {"id": "FIG-048a6ec2b3fa6174", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Tabellarisches Konfigurations- und Zuordnungsmodell (Lookup-/Mapping-Tabelle für Zustandsübergänge).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Functional Cluster <strong>State Management (SM)</strong> (<code>AUTOSAR_SWS_StateManagement</code>, Kapitel 7 <em>Functional Specification</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition deterministischer, unbedingter Fehler-Wiederherstellungsübergänge (<em>unconditional recovery transitions</em>) innerhalb einer SM-Zustandsmaschine (<em>StateMachine</em>). Die Tabelle verknüpft platform- bzw. prozessseitig detektierte Laufzeitfehler (gemeldet durch <strong>Execution Management / EM</strong> oder <strong>Platform Health Management / PHM</strong>) direkt mit definierten Folgezuständen (z. B. Notlauf, Degradierung, Prozess-Restart, Safe State).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Datenstruktur:</strong></li>\n<li><strong><code>ErrorRecoveryTable</code>:</strong> Konfigurations-Artefakt im State-Management-Metamodell zur Abbildung von Fehlerereignissen auf Zielzustände.</li>\n<li><strong><code>Execution Error</code> (Spalte 1):</strong> Diskrete numerische Fehlerbezeichner (<code>uint32</code>/Integer-Werte), die spezifische Fehlerursachen oder Exit-Zustände von Prozessen bzw. Function Groups abbilden (im Schaubild: <code>11</code>, <code>12</code>, <code>111</code>, <code>23</code>, <code>24</code>, <code>244</code>). Im Metamodell korrespondieren diese mit Attributen des Typs <code>ProcessExecutionError.executionError</code>.</li>\n<li><strong><code>Next State</code> (Spalte 2):</strong> Zielzustands-Identifikatoren bzw. Indizes der Zustandsmaschine (<code>0</code>, <code>2</code>, <code>3</code>, <code>4</code>, <code>5</code>), die nach Auftreten des zugehörigen Fehlers eingenommen werden müssen.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>$N : 1$-Relation:</strong> Mehrere disjunkte Fehlerursachen können auf denselben Folgezustand abgebildet werden (z. B. führen sowohl Fehler <code>11</code> als auch <code>111</code> zu <code>Next State = 2</code>).</li>\n<li><strong>$1 : 1$-Eindeutigkeit:</strong> Jedem definierten <code>Execution Error</code> ist innerhalb der Tabelle genau ein deterministischer <code>Next State</code> zugewiesen (Injektivität vom Fehler auf den Folgezustand; keine Mehrdeutigkeit/Nicht-Determinismus).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Fehlerdetektion & Signalisierung (Trigger):</strong> Ein Prozess terminiert fehlerhaft, verletzt Watchdog-/Deadline-Vorgaben oder meldet einen Ausfall an PHM/EM. EM/PHM meldet das resultierende <code>ExecutionError</code>-Ereignis asynchron an den State Management Cluster.</li>\n<li><strong>Tabellen-Lookup:</strong> SM fängt das Ereignis ab und evaluiert die <code>ErrorRecoveryTable</code> der betroffenen Zustandsmaschine anhand des empfangenen numerischen Fehlercodes.</li>\n<li>*<em>Unbedingter Zustandsübergang (</em>Unconditional Transition<em>):</em>*</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wird ein passender Eintrag gefunden, feuert der Zustandsübergang priorisiert und unmittelbar – reguläre Transition-Guards oder Einträge aus der <code>TransitionRequestTable</code> werden umgangen.</li>\n<li>Das System wechselt in den konfigurierten <code>Next State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Folgeaktionen:</strong> SM leitet Aktionen zur Fehlerbehebung ein (z. B. Anforderung neuer Function-Group-Zustände via <code>ara::exec</code>, Herunterfahren kompromittierter Prozesse oder System-Fallback nach <code>State 0</code>).</li>\n<li><strong>Abbruch-/Fehlerfall:</strong> Trifft ein <code>Execution Error</code> ein, der in der <code>ErrorRecoveryTable</code> nicht hinterlegt ist, greift das plattformspezifische Default-Verhalten (z. B. Übergang in einen globalen Machine-Safe-State oder System-Reset).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration im Execution- & SM-Manifest (ARXML):</strong></li>\n<li>Systemintegratoren müssen alle relevanten Exit-Codes und Health-Fehler (<code>ProcessExecutionError</code>) lückenlos auf gültige <code>ModeDeclaration</code>-Zustände mappen.</li>\n<li>Lücken in der Tabelle führen bei nicht abgefangenen Fehlern zu undefiniertem Verhalten oder unkontrollierten Platform-Resets.</li>\n<li><strong>Prioritätsmodell gegenüber <code>TransitionRequestTable</code>:</strong></li>\n<li>Einträge der <code>ErrorRecoveryTable</code> besitzen strikten Vorrang vor regulären externen Zustandsanfragen (z. B. von der <code>SMControlApplication</code> oder via Network Management).</li>\n<li><strong>Vermeidung von Reset-/Restart-Schleifen (Safety-Design nach ISO 26262):</strong></li>\n<li>Applikations- und Stack-Entwickler müssen sicherstellen, dass wiederkehrende Fehler nicht in unendlichen Übergangszyklen enden (z. B. ständiges Wiederanlaufen über denselben Folgezustand). Zustandsmaschinen müssen Zähler- oder Eskalationsstrategien für persistente Fehler vorsehen.</li>\n<li><strong>API-Vertrag:</strong></li>\n<li>Adaptive Applications müssen ihre internen Fehlerbehandlungsroutinen und Prozess-Rückgabewerte auf die numerischen Definitionen der <code>Execution Error</code>-Tabelle der jeweiligen Machine- und Function-Group-Konfiguration abstimmen.</li>\n</ul>"}, {"id": "FIG-c5e1fc6a6555d0f2", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Tabellarisches Konfigurations- und Zuordnungsmodell (Lookup-/Mapping-Tabelle für Zustandsübergänge).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Functional Cluster <strong>State Management (SM)</strong> (<code>AUTOSAR_SWS_StateManagement</code>, Kapitel 7 <em>Functional Specification</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition deterministischer, unbedingter Fehler-Wiederherstellungsübergänge (<em>unconditional recovery transitions</em>) innerhalb einer SM-Zustandsmaschine (<em>StateMachine</em>). Die Tabelle verknüpft platform- bzw. prozessseitig detektierte Laufzeitfehler (gemeldet durch <strong>Execution Management / EM</strong> oder <strong>Platform Health Management / PHM</strong>) direkt mit definierten Folgezuständen (z. B. Notlauf, Degradierung, Prozess-Restart, Safe State).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Datenstruktur:</strong></li>\n<li><strong><code>ErrorRecoveryTable</code>:</strong> Konfigurations-Artefakt im State-Management-Metamodell zur Abbildung von Fehlerereignissen auf Zielzustände.</li>\n<li><strong><code>Execution Error</code> (Spalte 1):</strong> Diskrete numerische Fehlerbezeichner (<code>uint32</code>/Integer-Werte: <code>11</code>, <code>12</code>, <code>111</code>, <code>23</code>, <code>24</code>) sowie das Wildcard-Schlüsselwort <code>ANY</code> zur Erfassung beliebiger sonstiger oder nicht explizit aufgeführter Fehlerursachen. Im Metamodell korrespondieren die numerischen Fehlercodes mit Attributen des Typs <code>ProcessExecutionError.executionError</code>.</li>\n<li><strong><code>Next State</code> (Spalte 2):</strong> Zielzustands-Identifikatoren der Zustandsmaschine in symbolischer Namensform (<code>Recovery</code>, <code>Startup</code>, <code>Suspend</code>, <code>Off</code>, <code>Shutdown</code>), die nach Auftreten des zugehörigen Fehlers eingenommen werden müssen.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>$N : 1$-Relation:</strong> Mehrere disjunkte Fehlerursachen können auf denselben Folgezustand abgebildet werden (z. B. führen sowohl Fehler <code>11</code> als auch <code>111</code> zu <code>Next State = Recovery</code>).</li>\n<li><strong>Default-/Catch-All-Zuordnung:</strong> Der Eintrag <code>ANY</code> erfasst alle nicht gesondert definierten Fehlercodes und weist ihnen deterministisch den Zielzustand <code>Shutdown</code> zu.</li>\n<li><strong>$1 : 1$-Eindeutigkeit:</strong> Jedem definierten <code>Execution Error</code> sowie dem Sammelbegriff <code>ANY</code> ist innerhalb der Tabelle genau ein deterministischer <code>Next State</code> zugewiesen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Fehlerdetektion & Signalisierung (Trigger):</strong> Ein Prozess terminiert fehlerhaft, verletzt Watchdog-/Deadline-Vorgaben oder meldet einen Ausfall an PHM/EM. EM/PHM meldet das resultierende <code>ExecutionError</code>-Ereignis asynchron an den State Management Cluster.</li>\n<li><strong>Tabellen-Lookup:</strong> SM fängt das Ereignis ab und evaluiert die <code>ErrorRecoveryTable</code> der betroffenen Zustandsmaschine anhand des empfangenen numerischen Fehlercodes.</li>\n<li>*<em>Unbedingter Zustandsübergang (</em>Unconditional Transition<em>):</em>*</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Stimmt der Fehlercode mit einem spezifischen Tabelleneintrag überein (<code>11</code>, <code>12</code>, <code>111</code>, <code>23</code>, <code>24</code>), feuert der Zustandsübergang unmittelbar in den zugehörigen symbolischen Zielzustand (<code>Recovery</code>, <code>Startup</code>, <code>Suspend</code>, <code>Off</code>).</li>\n<li>Ist der gemeldete Fehlercode nicht explizit hinterlegt, greift der Sammel- bzw. Wildcard-Eintrag <code>ANY</code>, und das System wechselt unmittelbar in den Zustand <code>Shutdown</code>.</li>\n<li>Reguläre Transition-Guards oder Einträge aus der <code>TransitionRequestTable</code> werden dabei umgangen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Folgeaktionen:</strong> SM leitet Aktionen zur Fehlerbehebung bzw. Stilllegung ein (z. B. Anforderung neuer Function-Group-Zustände via <code>ara::exec</code>, gezielter Neustart oder kontrolliertes Herunterfahren).</li>\n<li><strong>Abbruch-/Fehlerfall:</strong> Nur falls weder ein passender spezifischer Fehlercode noch ein <code>ANY</code>-Eintrag vorhanden ist, greift das plattformspezifische Default-Verhalten (z. B. Übergang in einen globalen Machine-Safe-State oder System-Reset).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration im Execution- & SM-Manifest (ARXML):</strong></li>\n<li>Systemintegratoren müssen alle relevanten Exit-Codes und Health-Fehler (<code>ProcessExecutionError</code>) lückenlos auf gültige <code>ModeDeclaration</code>-Zustände mappen.</li>\n<li>Lücken in der Tabelle führen bei nicht abgefangenen Fehlern zu undefiniertem Verhalten oder unkontrollierten Platform-Resets.</li>\n<li><strong>Prioritätsmodell gegenüber <code>TransitionRequestTable</code>:</strong></li>\n<li>Einträge der <code>ErrorRecoveryTable</code> besitzen strikten Vorrang vor regulären externen Zustandsanfragen (z. B. von der <code>SMControlApplication</code> oder via Network Management).</li>\n<li><strong>Vermeidung von Reset-/Restart-Schleifen (Safety-Design nach ISO 26262):</strong></li>\n<li>Applikations- und Stack-Entwickler müssen sicherstellen, dass wiederkehrende Fehler nicht in unendlichen Übergangszyklen enden (z. B. ständiges Wiederanlaufen über denselben Folgezustand). Zustandsmaschinen müssen Zähler- oder Eskalationsstrategien für persistente Fehler vorsehen.</li>\n<li><strong>API-Vertrag:</strong></li>\n<li>Adaptive Applications müssen ihre internen Fehlerbehandlungsroutinen und Prozess-Rückgabewerte auf die numerischen Definitionen der <code>Execution Error</code>-Tabelle der jeweiligen Machine- und Function-Group-Konfiguration abstimmen.</li>\n</ul>"}, {"id": "FIG-d6a397a71e0080ac", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Tabellarisches Konfigurations- und Zuordnungsmodell (Lookup-/Mapping-Tabelle für Zustandsübergänge).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Functional Cluster <strong>State Management (SM)</strong> (<code>AUTOSAR_SWS_StateManagement</code>, Kapitel 7 <em>Functional Specification</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition deterministischer, unbedingter Fehler-Wiederherstellungsübergänge (<em>unconditional recovery transitions</em>) innerhalb einer SM-Zustandsmaschine (<em>StateMachine</em>). Die Tabelle verknüpft platform- bzw. prozessseitig detektierte Laufzeitfehler (gemeldet durch <strong>Execution Management / EM</strong> oder <strong>Platform Health Management / PHM</strong>) direkt mit definierten Folgezuständen (z. B. Notlauf, Degradierung, Prozess-Restart, Safe State).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Datenstruktur:</strong></li>\n<li><strong><code>ErrorRecoveryTable</code>:</strong> Konfigurations-Artefakt im State-Management-Metamodell zur Abbildung von Fehlerereignissen auf Zielzustände.</li>\n<li><strong><code>Error Code</code> (Spalte 1):</strong> Diskrete numerische Fehlerbezeichner (<code>uint32</code>/Integer-Werte: <code>11</code>, <code>12</code>, <code>111</code>, <code>23</code>, <code>24</code>) sowie das Wildcard-Schlüsselwort <code>ANY</code> zur Erfassung beliebiger sonstiger oder nicht explizit aufgeführter Fehlerursachen. Im Metamodell korrespondieren die numerischen Fehlercodes mit Attributen des Typs <code>ProcessExecutionError.executionError</code>.</li>\n<li><strong><code>Next State</code> (Spalte 2):</strong> Zielzustands-Identifikatoren der Zustandsmaschine in symbolischer Namensform (<code>Recovery</code>, <code>Startup</code>, <code>Suspend</code>, <code>Off</code>, <code>Shutdown</code>), die nach Auftreten des zugehörigen Fehlers eingenommen werden müssen.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>$N : 1$-Relation:</strong> Mehrere disjunkte Fehlerursachen können auf denselben Folgezustand abgebildet werden (z. B. führen sowohl Fehler <code>11</code> als auch <code>111</code> zu <code>Next State = Recovery</code>).</li>\n<li><strong>Default-/Catch-All-Zuordnung:</strong> Der Eintrag <code>ANY</code> erfasst alle nicht gesondert definierten Fehlercodes und weist ihnen deterministisch den Zielzustand <code>Shutdown</code> zu.</li>\n<li><strong>$1 : 1$-Eindeutigkeit:</strong> Jedem definierten <code>Error Code</code> sowie dem Sammelbegriff <code>ANY</code> ist innerhalb der Tabelle genau ein deterministischer <code>Next State</code> zugewiesen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Fehlerdetektion & Signalisierung (Trigger):</strong> Ein Prozess terminiert fehlerhaft, verletzt Watchdog-/Deadline-Vorgaben oder meldet einen Ausfall an PHM/EM. EM/PHM meldet das resultierende <code>ExecutionError</code>-Ereignis asynchron an den State Management Cluster.</li>\n<li><strong>Tabellen-Lookup:</strong> SM fängt das Ereignis ab und evaluiert die <code>ErrorRecoveryTable</code> der betroffenen Zustandsmaschine anhand des empfangenen numerischen Fehlercodes.</li>\n<li>*<em>Unbedingter Zustandsübergang (</em>Unconditional Transition<em>):</em>*</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Stimmt der Fehlercode mit einem spezifischen Tabelleneintrag überein (<code>11</code>, <code>12</code>, <code>111</code>, <code>23</code>, <code>24</code>), feuert der Zustandsübergang unmittelbar in den zugehörigen symbolischen Zielzustand (<code>Recovery</code>, <code>Startup</code>, <code>Suspend</code>, <code>Off</code>).</li>\n<li>Ist der gemeldete Fehlercode nicht explizit hinterlegt, greift der Sammel- bzw. Wildcard-Eintrag <code>ANY</code>, und das System wechselt unmittelbar in den Zustand <code>Shutdown</code>.</li>\n<li>Reguläre Transition-Guards oder Einträge aus der <code>TransitionRequestTable</code> werden dabei umgangen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Folgeaktionen:</strong> SM leitet Aktionen zur Fehlerbehebung bzw. Stilllegung ein (z. B. Anforderung neuer Function-Group-Zustände via <code>ara::exec</code>, gezielter Neustart oder kontrolliertes Herunterfahren).</li>\n<li><strong>Abbruch-/Fehlerfall:</strong> Nur falls weder ein passender spezifischer Fehlercode noch ein <code>ANY</code>-Eintrag vorhanden ist, greift das plattformspezifische Default-Verhalten (z. B. Übergang in einen globalen Machine-Safe-State oder System-Reset).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration im Execution- & SM-Manifest (ARXML):</strong></li>\n<li>Systemintegratoren müssen alle relevanten Exit-Codes und Health-Fehler (<code>ProcessExecutionError</code>) lückenlos auf gültige <code>ModeDeclaration</code>-Zustände mappen.</li>\n<li>Lücken in der Tabelle führen bei nicht abgefangenen Fehlern zu undefiniertem Verhalten oder unkontrollierten Platform-Resets.</li>\n<li><strong>Prioritätsmodell gegenüber <code>TransitionRequestTable</code>:</strong></li>\n<li>Einträge der <code>ErrorRecoveryTable</code> besitzen strikten Vorrang vor regulären externen Zustandsanfragen (z. B. von der <code>SMControlApplication</code> oder via Network Management).</li>\n<li><strong>Vermeidung von Reset-/Restart-Schleifen (Safety-Design nach ISO 26262):</strong></li>\n<li>Applikations- und Stack-Entwickler müssen sicherstellen, dass wiederkehrende Fehler nicht in unendlichen Übergangszyklen enden (z. B. ständiges Wiederanlaufen über denselben Folgezustand). Zustandsmaschinen müssen Zähler- oder Eskalationsstrategien für persistente Fehler vorsehen.</li>\n<li><strong>API-Vertrag:</strong></li>\n<li>Adaptive Applications müssen ihre internen Fehlerbehandlungsroutinen und Prozess-Rückgabewerte auf die numerischen Definitionen der <code>Execution Error</code>-Tabelle der jeweiligen Machine- und Function-Group-Konfiguration abstimmen.</li>\n</ul>"}], "trans": [{"from": "FIG-5902ee99c9e4eed4", "to": "FIG-048a6ec2b3fa6174", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-048a6ec2b3fa6174", "to": "FIG-c5e1fc6a6555d0f2", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Spalte 2 (<code>Next State</code>):</strong> Umstellung der Zielzustände von numerischen Zustandsindizes (<code>0</code>, <code>2</code>, <code>3</code>, <code>4</code>, <code>5</code>) auf symbolische Zustandsnamen (<code>Recovery</code>, <code>Startup</code>, <code>Suspend</code>, <code>Off</code>, <code>Shutdown</code>).</li>\n<li><strong>Spalte 1 (<code>Execution Error</code>), Zeile 6:</strong> Ersetzung des diskreten Fehlercodes <code>244</code> durch das Wildcard-Schlüsselwort <code>ANY</code>.</li>\n<li><strong>Zeile 6 (Tabelleneintrag):</strong> Einführung der Default-/Catch-All-Regel <code>ANY</code> $\\rightarrow$ <code>Shutdown</code> anstelle der spezifischen Zuordnung <code>244</code> $\\rightarrow$ <code>5</code>.</li>\n</ul>"}, {"from": "FIG-c5e1fc6a6555d0f2", "to": "FIG-d6a397a71e0080ac", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Spaltenkopf Spalte 1:</strong> Umbenennung von <code>Execution Error</code> in <code>Error Code</code>.</li>\n</ul>"}]};
